#include <iostream>
#include <cmath>

int main() {
    int p, k;
    std::cin >> p >> k;
    const long long MOD = 1000000007;
    long long result;
    if (k == 0) {
        long long base = p % MOD;
        long long exp = p - 1;
        long long res = 1;
        long long b = base;
        while (exp > 0) {
            if (exp & 1) res = (res * b) % MOD;
            b = (b * b) % MOD;
            exp >>= 1;
        }
        result = res;
    } else if (k == 1) {
        long long base = p % MOD;
        long long exp = p;
        long long res = 1;
        long long b = base;
        while (exp > 0) {
            if (exp & 1) res = (res * b) % MOD;
            b = (b * b) % MOD;
            exp >>= 1;
        }
        result = res;
    } else {
        long long x = 1;
        int i;
        for (i = 1; i <= p; ++i) {
            x = (x * k) % p;
            if (x == 1) {
                break;
            }
        }
        long long exp = (p - 1) / i;
        long long base = p % MOD;
        long long res = 1;
        long long b = base;
        while (exp > 0) {
            if (exp & 1) res = (res * b) % MOD;
            b = (b * b) % MOD;
            exp >>= 1;
        }
        result = res;
    }
    std::cout << result << std::endl;
    return 0;
}
